package com.attycompanion;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("attycompanion")
public interface AttyConfig extends Config
{
    @ConfigItem(keyName = "showDialogue", name = "Show dialogue", description = "Show Atty's occasional remarks")
    default boolean showDialogue() { return true; }

    @ConfigItem(keyName = "hardcoreReminders", name = "Hardcore reminders", description = "Occasionally remind you to check food and supplies")
    default boolean hardcoreReminders() { return true; }

}

package com.attycompanion;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.util.ImageUtil;

/** Draws the 2D companion near the projected player position. Never changes the game scene. */
public class AttyOverlay extends Overlay
{
    private static final int FOLLOW_DISTANCE = 160;

    @Inject private Client client;
    @Inject private AttyPlugin plugin;
    @Inject private AttyConfig config;

    @Inject
    public AttyOverlay()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        Player player = client.getLocalPlayer();
        if (player == null || player.getLocalLocation() == null)
        {
            return null;
        }
        LocalPoint location = player.getLocalLocation();
        int plane = client.getPlane();
        // RuneLite's orientation increases clockwise from south in 2048 steps.
        double angle = player.getCurrentOrientation() * (Math.PI / 1024);
        LocalPoint follower = new LocalPoint(
            location.getX() + (int) Math.round(FOLLOW_DISTANCE * Math.sin(angle)),
            location.getY() + (int) Math.round(FOLLOW_DISTANCE * Math.cos(angle)),
            location.getWorldView());
        net.runelite.api.Point projected = Perspective.localToCanvas(client, follower, plane);
        if (projected == null)
        {
            return null;
        }
        int x = projected.getX();
        int y = projected.getY();
        drawCompanion(g, x, y);
        String message = plugin.getVisibleMessage();
        if (message != null && config.showDialogue())
        {
            drawSpeech(g, x, y - 48, message);
        }
        return null;
    }

    private static final BufferedImage COMPANION =
        ImageUtil.loadImageResource(AttyOverlay.class, "atty.png");

    private void drawCompanion(Graphics2D g, int x, int y)
    {
        g.setColor(new Color(19, 18, 15, 105));
        g.fillOval(x - 15, y - 5, 30, 9);
        g.drawImage(COMPANION, x - COMPANION.getWidth() / 2, y - COMPANION.getHeight(), null);
    }

    private void drawSpeech(Graphics2D g, int x, int y, String message)
    {
        Font oldFont = g.getFont();
        g.setFont(new Font("SansSerif", Font.BOLD, 12));
        FontMetrics fm = g.getFontMetrics();
        int width = Math.min(310, fm.stringWidth(message) + 20);
        int bx = x - width / 2;
        int by = y - 31;
        g.setColor(new Color(15, 26, 50, 230));
        g.fillRoundRect(bx, by, width, 27, 12, 12);
        g.setColor(new Color(108, 191, 255));
        g.drawRoundRect(bx, by, width, 27, 12, 12);
        g.setColor(Color.WHITE);
        g.drawString(message, bx + 10, by + 18);
        g.setFont(oldFont);
    }
}

package com.attycompanion;

import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "Atty Companion", description = "A cosmetic blue companion with GZs and gentle reminders", tags = {"cosmetic", "companion", "level", "ironman"})
public class AttyPlugin extends Plugin
{
    private static final String[] CHATTER = {
        "Fishing lvls?", "Nice.", "Catherby still feels like home.",
        "Sea Shanty 2 never gets old.", "Remember when everyone fished lobsters?",
        "No XP/hour pressure here.", "One small grind at a time."
    };
    private static final String[] REMINDERS = {
        "Hardcore check: food and escape route?",
        "Keep that red helm safe.",
        "Check your supplies before a risky quest."
    };

    @Inject private Client client;
    @Inject private OverlayManager overlayManager;
    @Inject private AttyOverlay overlay;
    @Inject private AttyConfig config;

    private final Map<Skill, Integer> knownLevels = new EnumMap<>(Skill.class);
    private String message;
    private Instant messageUntil = Instant.EPOCH;
    private int ticksUntilChatter = 180;

    @Provides
    AttyConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(AttyConfig.class);
    }

    @Override
    protected void startUp()
    {
        knownLevels.clear();
        message = null;
        ticksUntilChatter = 180;
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        knownLevels.clear();
        message = null;
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        Skill skill = event.getSkill();
        int level = event.getLevel();
        Integer previous = knownLevels.put(skill, level);
        // The first observed value is a baseline, not a level-up.
        if (previous != null && level > previous)
        {
            say("GZ! " + skill.getName() + " " + level + "!", 14);
        }
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        if (--ticksUntilChatter > 0)
        {
            return;
        }
        // A remark about every 3-6 minutes, not constant interruptions.
        ticksUntilChatter = ThreadLocalRandom.current().nextInt(300, 600);
        if (!config.showDialogue() || Instant.now().isBefore(messageUntil))
        {
            return;
        }
        boolean reminder = config.hardcoreReminders() && ThreadLocalRandom.current().nextInt(5) == 0;
        String[] pool = reminder ? REMINDERS : CHATTER;
        say(pool[ThreadLocalRandom.current().nextInt(pool.length)], 10);
    }

    private void say(String text, int seconds)
    {
        message = text;
        messageUntil = Instant.now().plus(Duration.ofSeconds(seconds));
    }

    String getVisibleMessage()
    {
        return Instant.now().isBefore(messageUntil) ? message : null;
    }
}

package com.attycompanion;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/** Development-only entry point; does not install the plugin in normal RuneLite. */
public class AttyPluginTest
{
    public static void main(String[] args) throws Exception
    {
        System.setProperty("runelite.developer-mode","true");

        ExternalPluginManager.loadBuiltin(AttyPlugin.class);
        RuneLite.main(args);
    }
}
